return (async function (Hive) {
  let settings = { showSeconds: true, hour24: false };
  try { settings = Object.assign(settings, await Hive.settings.load()); } catch {}
  const listeners = new Set();
  Hive.settings.onChange(next => { settings = Object.assign(settings, next || {}); listeners.forEach(fn => fn()); });

  function mount(host) {
    host.classList.add('hsc');
    host.innerHTML = '<div class="hsc-wrap"><div class="hsc-time">--:--</div><div class="hsc-date"></div><div class="hsc-track hsc-empty"><img class="hsc-art" alt=""><div class="hsc-meta"><div class="hsc-title"></div><div class="hsc-artist"></div></div></div></div>';
    const timeEl = host.querySelector('.hsc-time');
    const dateEl = host.querySelector('.hsc-date');
    const trackBox = host.querySelector('.hsc-track');
    const artEl = host.querySelector('.hsc-art');
    const titleEl = host.querySelector('.hsc-title');
    const artistEl = host.querySelector('.hsc-artist');

    function tick() {
      const now = new Date();
      const opts = { hour: '2-digit', minute: '2-digit', hour12: !settings.hour24 };
      if (settings.showSeconds) opts.second = '2-digit';
      timeEl.textContent = now.toLocaleTimeString([], opts);
      dateEl.textContent = now.toLocaleDateString([], { weekday: 'long', month: 'long', day: 'numeric' });
    }
    function showTrack(track) {
      if (!track || !track.title) { trackBox.classList.add('hsc-empty'); return; }
      trackBox.classList.remove('hsc-empty');
      titleEl.textContent = track.title || '';
      artistEl.textContent = track.artist || '';
      const cover = Hive.player.getCoverUrl(track);
      if (cover) { artEl.src = cover; artEl.style.display = 'block'; } else { artEl.removeAttribute('src'); artEl.style.display = 'none'; }
    }
    artEl.onerror = () => { artEl.style.display = 'none'; };
    tick();
    const timer = setInterval(tick, 500);
    listeners.add(tick);
    const offTrack = Hive.events.on('track-change', showTrack);
    showTrack(Hive.player.getCurrent());
    return () => { clearInterval(timer); listeners.delete(tick); offTrack(); };
  }

  let cleanup = null;
  Hive.ui.registerView({
    id: 'clock',
    title: 'Studio Clock',
    description: 'Minimal studio clock with the playing song',
    mount: (host) => { cleanup = mount(host); },
    unmount: () => { if (cleanup) { cleanup(); cleanup = null; } }
  });
})(Hive);
